import {useEffect,useState} from 'react';import {BookOpen,Users,ArrowLeftRight,AlertTriangle,Bookmark,ReceiptText} from 'lucide-react';import api,{message} from '../services/api.js';import StatCard from '../components/StatCard.jsx';
export default function Dashboard(){const [d,setD]=useState(null);const [err,setErr]=useState('');useEffect(()=>{api.get('/loans/dashboard').then(r=>setD(r.data)).catch(e=>setErr(message(e)))},[]);if(err)return <div className="alert error">{err}</div>;if(!d)return <div className="loading">Loading dashboard...</div>;return <><div className="page-head"><div><h2>Dashboard</h2><p>Overview of your library activity.</p></div></div><div className="stats"><StatCard label="Books" value={d.books} icon={BookOpen} muted={`${d.totalCopies} total copies`}/><StatCard label="Members" value={d.members} icon={Users}/><StatCard label="Currently Issued" value={d.issuedLoans} icon={ArrowLeftRight} muted={`${d.availableCopies} copies available`}/><StatCard label="Overdue" value={d.overdueLoans} icon={AlertTriangle}/><StatCard label="Reservations" value={d.pendingReservations} icon={Bookmark} muted="pending"/><StatCard label="Unpaid Fines" value={d.unpaidFines} icon={ReceiptText}/></div><div className="panel-grid"><div className="panel"><h3>Library health</h3><div className="progress-row"><span>Available copies</span><b>{d.totalCopies?Math.round(d.availableCopies/d.totalCopies*100):0}%</b></div><div className="progress"><span style={{width:`${d.totalCopies?d.availableCopies/d.totalCopies*100:0}%`}}/></div><div className="mini-grid"><div><small>Returned loans</small><strong>{d.returnedLoans}</strong></div><div><small>Active loans</small><strong>{d.issuedLoans}</strong></div><div><small>Overdue loans</small><strong>{d.overdueLoans}</strong></div></div></div><div className="panel"><h3>Quick actions</h3><div className="quick"><a href="/books">Add or manage books</a><a href="/members">Manage members</a><a href="/loans">Issue / return a book</a><a href="/reports">Open reports</a></div></div></div></>}
